func ptrReplyTemplate(p unsafe.Pointer, c int32) any {
	r := (*triage.ReplyTemplate)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Name
	case 4:
		return &r.Body
	case 5:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 6:
		return &r.Version
	case 7:
		return &r.CreatedAt
	case 8:
		return &r.UpdatedAt
	}
	return nil
}

func valueReplyTemplate(p unsafe.Pointer, c int32) any {
	r := (*triage.ReplyTemplate)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Name
	case 4:
		return r.Body
	case 5:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 6:
		return r.Version
	case 7:
		return r.CreatedAt
	case 8:
		return r.UpdatedAt
	}
	return nil
}

