func ptrResponseTarget(p unsafe.Pointer, c int32) any {
	r := (*triage.ResponseTarget)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.Classification))
	case 3:
		return (*int64)(unsafe.Pointer(&r.Minutes))
	case 4:
		return (*string)(unsafe.Pointer(&r.UpdatedByID))
	case 5:
		return &r.CreatedAt
	case 6:
		return &r.UpdatedAt
	}
	return nil
}

func valueResponseTarget(p unsafe.Pointer, c int32) any {
	r := (*triage.ResponseTarget)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.Classification)
	case 3:
		return int64(r.Minutes)
	case 4:
		if r.UpdatedByID == "" {
			return nil
		}
		return string(r.UpdatedByID)
	case 5:
		return r.CreatedAt
	case 6:
		return r.UpdatedAt
	}
	return nil
}

