func newRule() unsafe.Pointer { return unsafe.Pointer(new(triage.Rule)) }

func newNRule(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]triage.Rule, n))) }

func ptrRule(p unsafe.Pointer, c int32) any {
	r := (*triage.Rule)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Classification))
	case 4:
		return (*string)(unsafe.Pointer(&r.SenderScope))
	case 5:
		return &r.Sender
	case 6:
		return (*string)(unsafe.Pointer(&r.MailboxID))
	case 7:
		return (*string)(unsafe.Pointer(&r.Action))
	case 8:
		return (*string)(unsafe.Pointer(&r.AssigneeID))
	case 9:
		return &r.Enabled
	case 10:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 11:
		return &r.MatchCount
	case 12:
		return &r.LastMatchedAt
	case 13:
		return (*string)(unsafe.Pointer(&r.LastMessageID))
	case 14:
		return &r.Version
	case 15:
		return &r.CreatedAt
	case 16:
		return &r.UpdatedAt
	}
	return nil
}

func valueRule(p unsafe.Pointer, c int32) any {
	r := (*triage.Rule)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Classification)
	case 4:
		return string(r.SenderScope)
	case 5:
		if r.Sender == "" {
			return nil
		}
		return r.Sender
	case 6:
		if r.MailboxID == "" {
			return nil
		}
		return string(r.MailboxID)
	case 7:
		return string(r.Action)
	case 8:
		if r.AssigneeID == "" {
			return nil
		}
		return string(r.AssigneeID)
	case 9:
		return r.Enabled
	case 10:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 11:
		return r.MatchCount
	case 12:
		if r.LastMatchedAt == 0 {
			return nil
		}
		return r.LastMatchedAt
	case 13:
		if r.LastMessageID == "" {
			return nil
		}
		return string(r.LastMessageID)
	case 14:
		return r.Version
	case 15:
		return r.CreatedAt
	case 16:
		return r.UpdatedAt
	}
	return nil
}

