func ptrSenderHint(p unsafe.Pointer, c int32) any {
	r := (*triage.SenderHint)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return &r.SenderDomain
	case 3:
		return (*string)(unsafe.Pointer(&r.Classification))
	case 4:
		return (*int64)(unsafe.Pointer(&r.Corrections))
	case 5:
		return &r.LastCorrectedAt
	}
	return nil
}

func valueSenderHint(p unsafe.Pointer, c int32) any {
	r := (*triage.SenderHint)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return r.SenderDomain
	case 3:
		return string(r.Classification)
	case 4:
		return int64(r.Corrections)
	case 5:
		return r.LastCorrectedAt
	}
	return nil
}

