func ptrView(p unsafe.Pointer, c int32) any {
	r := (*triage.View)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return &r.Name
	case 5:
		return &r.Query
	case 6:
		return (*int64)(unsafe.Pointer(&r.Position))
	case 7:
		return &r.CreatedAt
	case 8:
		return &r.UpdatedAt
	}
	return nil
}

